    38	    public List<Message> all() {
    39	        try (Connection connection = dataSource.getConnection();
    40	                PreparedStatement select = connection.prepareStatement(
    41	                        "SELECT id, channel, recipient, subject, body, status FROM messages ORDER BY id");
    42	                ResultSet rows = select.executeQuery()) {
    43	            List<Message> messages = new ArrayList<>();
    44	            while (rows.next()) {
    45	                messages.add(new Message(
