    47	                        rows.getString("channel"),
    48	                        rows.getString("recipient"),
    49	                        rows.getString("subject"),
    50	                        rows.getString("body"),
    51	                        MessageStatus.valueOf(rows.getString("status"))));
    52	            }
    53	            return messages;
    54	        } catch (SQLException failure) {
